-- What's new: welcome window
L["A new welcome window"] = "Una nueva ventana de bienvenida"
L["Pick how much Cinematic does, Subtle, Balanced or Cinema, then Customize changes one part at a time: your layout, camera, look, Visions, chat and sound."] = "Elige cuánto hace Cinematic, Discreto, Equilibrado o Cine, y luego Personalizar cambia una parte cada vez: tu disposición, cámara, aspecto, Visiones, chat y sonido."

-- What's new: Name styles
L["Name styles"] = "Estilos de nombre"
L["The names Cinematic draws on faded nameplates in CineMode have a page of their own: their colors, outline, opacity, size and height, with presets and a preview."] = "Los nombres que Cinematic dibuja en las placas atenuadas en el modo Cine tienen su propia página: sus colores, contorno, opacidad, tamaño y altura, con estilos predefinidos y una vista previa."

-- What's new: Nameplate marks
L["Nameplate marks"] = "Marcas en las placas"
L["Marks and colors for your focus, the unit under the mouse and a target that's attacking you, not just your target, each with its own look, when it shows, and rows for just enemies or friends. Set them on the Style hub's Nameplates page."] = "Marcas y colores para tu foco, la unidad bajo el ratón y un objetivo que te ataca, no solo tu objetivo, cada uno con su propio aspecto, cuándo se muestra y filas solo para enemigos o amistosos. Ajústalos en la página Placas de nombre del grupo Estilo."

-- What's new: Socials
L["A new page in the Community hub with links to the Discord, YouTube, CurseForge and GitHub, ready to copy."] = "Una nueva página en el grupo Comunidad con enlaces al Discord, YouTube, CurseForge y GitHub, listos para copiar."

-- What's new: Cameras page
L["Cameras page"] = "Página de cámaras"
L["Camera Modes and Camera Triggers are now one Cameras page: a row for each trigger (an emote, a campfire, going AFK, a flight...) with the camera it starts, its music and CineMode, and where it can start. Copy a row to give a trigger a different camera in other places."] = "Modos de cámara y Activadores de cámara son ahora una sola página de Cámaras: una fila para cada activador (un gesto, una hoguera, quedarte ausente, un vuelo...) con la cámara que inicia, su música y CineMode, y dónde puede iniciarse. Copia una fila para darle a un activador otra cámara en otros lugares."

