-- What's new: achievement progress cards (Changelog.lua)
L["Achievement progress cards"] = "Tarjetas de progreso de logros"
L["Three new cards in the top bar: how much of a zone you've explored, an achievement with one step left, and an achievement's step done. Each shows at most once every 10 minutes; on in the Cinema profile."] = "Tres tarjetas nuevas en la barra superior: cuánto has explorado de una zona, un logro al que le falta un paso y un paso de un logro completado. Cada una sale como mucho una vez cada 10 minutos; activadas en el perfil Cine."

-- What's new: ClassicUI Forever support (Changelog.lua)
L["ClassicUI Forever support"] = "Compatibilidad con ClassicUI Forever"
L["ClassicUI Forever's action bars, bar art and quest watch now fade with Cinematic, and come back when you hover them."] = "Las barras de acción, el arte de la barra y el seguimiento de misiones de ClassicUI Forever ahora se desvanecen con Cinematic y vuelven al pasar el ratón por encima."

-- What's new: support for 7 more addons (Changelog.lua)
L["Support for 7 more addons"] = "Compatibilidad con 7 addons más"
L["BigWigs, TomTom, HealBot Continued and Titan Panel get rows of their own and fade with Cinematic. Platynator and Threat Plates nameplates fade in CineMode, and Prat 3.0's chat follows the Chat page."] = "BigWigs, TomTom, HealBot Continued y Titan Panel tienen sus propias filas y se desvanecen con Cinematic. Las placas de nombre de Platynator y Threat Plates se desvanecen en CineMode, y el chat de Prat 3.0 sigue la página de Chat."

-- What's new: Lore Forever support (Changelog.lua)
L["Lore Forever support"] = "Compatibilidad con Lore Forever"
L["Lore Forever's subtitles, floating player, new page note and pin card get rows of their own and fade with Cinematic. With Custom dialogue frames on, a Play button on the box with the NPC's words plays the quest's narration or stops it."] = "Los subtítulos, el reproductor flotante, el aviso de página nueva y la tarjeta de chincheta de Lore Forever tienen sus propias filas y se desvanecen con Cinematic. Con los marcos de diálogo personalizados activados, un botón de reproducir en el cuadro con las palabras del PNJ reproduce la narración de la misión o la detiene."

-- What's new: Nameplates hub (Changelog.lua)
L["Nameplates hub"] = "Centro de placas de nombre"
L["Nameplates have a hub of their own: which show, the new Icons page for class and role icons, and their looks. Each kind of plate can have its own parts, and each Nameplate Style row its own bar, border, name font and level box."] = "Las placas de nombre tienen su propio centro: cuáles se muestran, la nueva página de Iconos para los iconos de clase y de rol, y su aspecto. Cada tipo de placa puede tener sus propias partes, y cada fila de Estilo de placas su propia barra, borde, fuente del nombre y recuadro de nivel."

-- What's new: Frames Forever and ShamanPower support (Changelog.lua)
L["Frames Forever and ShamanPower support"] = "Compatibilidad con Frames Forever y ShamanPower"
L["Frames Forever's unit frames follow the Game Frames rows of the frames they replace. ShamanPower's totem bar fades with the Totem bar row, and its cooldown bar gets a row of its own."] = "Los marcos de unidad de Frames Forever siguen las filas de Marcos del juego de los marcos que reemplazan. La barra de tótems de ShamanPower se desvanece con la fila de Barra de tótems, y su barra de reutilización tiene su propia fila."

-- What's new: Shoulder Cam (Changelog.lua)
L["An over-the-shoulder camera: you sit to one side of the screen and stay there as you zoom. Swap shoulders with a key, turn toward the NPCs you talk to and the enemies you target, and let your cast bar and resources slide along with you."] = "Una cámara sobre el hombro: quedas a un lado de la pantalla y ahí sigues al hacer zoom. Cambia de hombro con una tecla, gira hacia los PNJ con los que hablas y los enemigos que seleccionas, y deja que tu barra de lanzamiento y tus recursos se deslicen contigo."

-- Shoulder Cam (ShoulderCam.lua, ShoulderCalibrate.lua, ProfileChoices.lua): public since 2026-11-15
L["The Shoulder Cam uses one of Blizzard's experimental camera settings. The game would warn about it every time you log in, so Cinematic keeps that warning away while the Shoulder Cam is on. If the camera ever acts up, turn the Shoulder Cam off and your own camera settings come back."] = "La Cámara al hombro usa uno de los ajustes de cámara experimentales de Blizzard. El juego avisaría de ello cada vez que entras, así que Cinematic aparta ese aviso mientras la Cámara al hombro está activada. Si la cámara alguna vez se comporta raro, desactiva la Cámara al hombro y vuelven tus propios ajustes de cámara."
L["Accept"] = "Aceptar"
L["Shoulder Cam is paused while the gamepad UI is on: the game keeps your character centered in it."] = "La Cámara al hombro está en pausa mientras la interfaz de mando está activada: el juego mantiene a tu personaje centrado en ella."
L["Swap shoulders (Shoulder Cam)"] = "Cambiar de hombro (Cámara al hombro)"
L["Where the camera sits, when it turns, and when it steps back behind you."] = "Dónde se coloca la cámara, cuándo gira y cuándo vuelve detrás de ti."
L["Follow HUD"] = "HUD que te sigue"
