L["Not supported at the moment"] = "No compatible por ahora"
L["The Shoulder Cam doesn't work with the gamepad UI yet. While it's on, the game keeps your character in the middle of the screen, so the Shoulder Cam waits behind you and comes back by itself when you turn the gamepad UI off (Options > Gamepad (Beta) > Enable Gamepad UI)."] = "La Cámara al hombro aún no funciona con la interfaz de mando. Mientras está activada, el juego mantiene a tu personaje en el centro de la pantalla, así que la Cámara al hombro espera detrás de ti y vuelve sola al desactivar la interfaz de mando (Opciones > Mando (beta) > Activar interfaz de mando)."
L["Calibrating my camera, please ignore this line for a moment: I'm measuring where my character sits on the screen as the camera moves over my shoulder. Thanks for your patience!"] = "Calibrando mi cámara, ignorad esta línea un momento: estoy midiendo dónde queda mi personaje en la pantalla mientras la cámara se pone sobre mi hombro. ¡Gracias por la paciencia!"
L["On foot"] = "A pie"
L["Form %s"] = "Forma %s"
L["Calibration stopped"] = "Calibración detenida"
L["Calibration: not enough readings"] = "Calibración: no hay suficientes lecturas"
L["Try again somewhere open and flat."] = "Inténtalo de nuevo en un lugar abierto y llano."
L["Saved, and in use now. Share it from the Calibrate tab."] = "Guardado, y en uso ya. Compártelo desde la pestaña Calibrar."
L["The readings disagree (%.2f apart): try again somewhere open and flat."] = "Las lecturas no coinciden (%.2f de diferencia): inténtalo de nuevo en un lugar abierto y llano."
L["Calibrating: step %d of %d"] = "Calibrando: paso %d de %d"
L["Stand still and leave the camera alone."] = "Quédate quieto y deja la cámara en paz."
L["Say it again and go on"] = "Decirlo otra vez y seguir"
L["The bubble's gone: click the button below to go on."] = "El bocadillo se ha ido: haz clic en el botón de abajo para seguir."
L["A fight started."] = "Ha empezado un combate."
L["You picked a target: clear it (Esc) and start again."] = "Has elegido un objetivo: quítalo (Esc) y empieza de nuevo."
L["It's already running."] = "Ya está en marcha."
L["Clear your target first (Esc)."] = "Quita primero tu objetivo (Esc)."
L["This client can't read chat bubbles."] = "Este cliente no puede leer los bocadillos de chat."
L["Not in a dungeon, raid or battleground."] = "No en una mazmorra, banda o campo de batalla."
L["Stopped."] = "Detenido."
L["Calibrate the Shoulder Cam for %s?\n\nIt says a line in /say a few times (everyone near you sees it), so somewhere quiet is best. Stand still on open, flat ground and leave the camera alone for about 10 seconds."] = "¿Calibrar la Cámara al hombro para %s?\n\nDice una línea en /decir varias veces (todos los que están cerca la ven), así que mejor un lugar tranquilo. Quédate quieto en suelo abierto y llano y deja la cámara en paz unos 10 segundos."
L["Your Shoulder Cam measurements"] = "Tus medidas de la Cámara al hombro"
L["Your measurements on one line: copy it and paste it to us on Discord or GitHub."] = "Tus medidas en una línea: cópiala y pégala para nosotros en Discord o GitHub."
L["Your measurements"] = "Tus medidas"
L["Character"] = "Personaje"
L["Form"] = "Forma"
L["Date"] = "Fecha"
L["None yet: calibrate to add one."] = "Ninguna aún: calibra para añadir una."
L["You now: |cffffffff%s|r, size |cffffffff%.2f|r |cff9d9d9d(%s)|r"] = "Tú ahora: |cffffffff%s|r, tamaño |cffffffff%.2f|r |cff9d9d9d(%s)|r"
L["Good"] = "Buena"
L["Not used"] = "Sin usar"
L["Cinema, over your shoulder. The camera sits over your shoulder with you to one side of the screen, and your resources, cast bar and Cooldown Manager sit under you and slide along with you. Fights bring up your personal resource display instead of your portrait. Everything else is Cinema's: as little UI as possible, every camera, Vision and all the atmosphere."] = "Cine, sobre tu hombro. La cámara se coloca sobre tu hombro contigo a un lado de la pantalla, y tus recursos, barra de lanzamiento y Gestor de reutilización quedan bajo ti y se deslizan contigo. Los combates muestran tu pantalla de recursos personales en lugar de tu retrato. Todo lo demás es de Cine: la mínima interfaz, todas las cámaras, Visiones y toda la atmósfera."

-- Shoulder Cam: the welcome level, its test and Customize choices (ProfileChoices.lua, Welcome.lua, ShowMe.lua)
L["Your resources at the bottom middle, everything hung on them"] = "Tus recursos abajo en el centro, todo colgado de ellos"
L["Cinema, with the camera over your shoulder."] = "Cine, con la cámara sobre tu hombro."
L["It uses one of Blizzard's experimental camera settings: picking it or its test agrees to that. Turn the Shoulder Cam off and your own camera settings come back."] = "Usa uno de los ajustes de cámara experimentales de Blizzard: elegirlo o probarlo es aceptarlo. Desactiva la Cámara al hombro y vuelven tus propios ajustes de cámara."
L["The camera moves over your shoulder, with you to one side of the screen. This glides in, swaps shoulders once and glides back. It uses one of Blizzard's experimental camera settings: trying it agrees to that, and your own camera settings come back after."] = "La cámara se coloca sobre tu hombro, contigo a un lado de la pantalla. Entra suavemente, cambia de hombro una vez y vuelve. Usa uno de los ajustes de cámara experimentales de Blizzard: probarlo es aceptarlo, y tus propios ajustes de cámara vuelven después."
L["Over your shoulder outdoors, off your mount and out of dungeons and raids."] = "Sobre tu hombro al aire libre, sin montura y fuera de mazmorras y bandas."

-- Shoulder Cam: the welcome level, its test and Customize choices (ProfileChoices.lua, Welcome.lua, ShowMe.lua)
L["Cinematic leaves your Edit Mode layout as it is; your personal resource display on, up in fights"] = "Cinematic deja tu diseño del Modo Edición como está; tu pantalla de recursos personales activada, visible en combate"

-- Camera hub: the Special Cams section (Options.lua HUBS)
L["Special Cams"] = "Cámaras especiales"

-- Shoulder Cam page: Clear target on Esc while interacting with an NPC
L["Clear target on Esc while interacting with an NPC"] = "Quitar objetivo con Esc al hablar con un PNJ"

-- What's new: A new Interface hub (Changelog.lua)
L["A new Interface hub"] = "Un nuevo centro de Interfaz"

-- What's new: New zone card (Changelog.lua)
L["New zone card"] = "Tarjeta de zona nueva"
L["The first time you enter a zone like Westfall or Duskwood, its name slams onto the screen in huge white capitals. Comes with the new Headline style."] = "La primera vez que entras en una zona como Páramos de Poniente o Bosque del Ocaso, su nombre cae de golpe en la pantalla en enormes mayúsculas blancas. Llega con el nuevo estilo Titular."

