L["open a page by its names from the left list down, e.g. /cine find ui visibility minimap"] = "abre una página por sus nombres desde la lista de la izquierda hacia abajo, p. ej. /cine find interfaz visibilidad minimapa"
L["look only on those pages, e.g. /cine find Style||Names fade time"] = "busca solo en esas páginas, p. ej. /cine find Estilo||Nombres desvanecer"
