L["Pop out to drag the window anywhere, or dock it beside the settings."] = "Sácala para arrastrar la ventana a cualquier sitio, o acóplala junto a las opciones."
L["0 s"] = "0 s"
L["Speed match"] = "Igualar velocidad"
L["%s yd/s"] = "%s m/s"
L["%s°/s"] = "%s°/s"
L["%s s"] = "%s s"
L["Every camera as a script of small steps you can copy and change."] = "Cada cámara como un guion de pequeños pasos que puedes copiar y cambiar."
L["Deletes this script; click twice to confirm."] = "Borra este guion; haz clic dos veces para confirmar."
L["Puts our script back in place of your changes; click twice to confirm."] = "Restaura nuestro guion en lugar de tus cambios; haz clic dos veces para confirmar."
L["Runs the camera through this script now; click again to stop."] = "Ejecuta ahora la cámara con este guion; haz clic otra vez para detenerla."
L["Untick to keep the camera running when this happens."] = "Desmarca para que la cámara siga en marcha cuando ocurra esto."
L["Shows a Stop camera button on screen while this camera runs."] = "Muestra un botón Detener cámara en pantalla mientras funciona esta cámara."
L["What stops the camera, plus its edge haze and Stop button."] = "Qué detiene la cámara, además de su bruma de bordes y su botón Detener."
L["Turns this tab of the script on or off."] = "Activa o desactiva esta pestaña del guion."
L["Not a script yet: it needs %s, which the runner doesn't have yet."] = "Aún no es un guion: necesita %s, que el ejecutor todavía no tiene."
L["Starts when: no trigger yet."] = "Empieza cuando: aún sin activador."

