L["The language Cinematic's text is in; a change needs a reload."] = "El idioma del texto de Cinematic; cambiarlo requiere recargar."
L["The look of Cinematic's settings windows: HD is flat and dark, and SD looks like the game's own."] = "El aspecto de las ventanas de opciones de Cinematic: HD es plano y oscuro, y SD se parece al del propio juego."
L["The game's %s is off"] = "La opción %s del juego está desactivada"
