L["Off. Right-click to turn all its tabs on."] = "Desactivado. Clic derecho para activar todas sus pestañas."
L["Cinematic is about bringing Azeroth to life: your screen changes with the moment you're in, hiding what you don't need and showing what you do."] = "Cinematic quiere dar vida a Azeroth: tu pantalla cambia según el momento, ocultando lo que no necesitas y mostrando lo que sí."
