L["Effects that play over the world when something happens."] = "Efectos que se reproducen sobre el mundo cuando pasa algo."
L["How the whole interface looks."] = "El aspecto de toda la interfaz."
L["The camera coming alive."] = "La cámara cobra vida."
L["How fast the UI fades, the Calm Timer, and what takes you out of CineMode."] = "Qué rápido se desvanece la interfaz, el Temporizador de calma y qué te saca de CineMode."
L["Your interface fades away but comes back when you need it to."] = "Tu interfaz se desvanece, pero vuelve cuando la necesitas."
