L["Runs this camera for 30 seconds where you stand."] = "Ejecuta esta cámara 30 segundos donde estás."
L["The camera slowly pulls back, then drifts in and out."] = "La cámara se aleja despacio y luego se acerca y aleja."
L["After you move the camera yourself, it waits this long before carrying on."] = "Después de mover tú la cámara, espera este tiempo antes de continuar."
L["Doing the emote or pressing the sit key."] = "Hacer el gesto o pulsar la tecla de sentarse."
L["Clicking Sit, Kneel or Lie down on the campfire card, or its fire button (Emote Vision)."] = "Hacer clic en Sentarse, Arrodillarse o Tumbarse en la tarjeta de hoguera, o en su botón de hoguera (visión de gestos)."
