L["Taking off on a flight path."] = "Despegar en una ruta de vuelo."
L["Talking to a quest giver."] = "Hablar con un PNJ de misión."
L["Talking to an NPC about a quest step."] = "Hablar con un PNJ sobre un paso de misión."
L["On flight paths, the camera sways side to side with an occasional fly-by."] = "En las rutas de vuelo, la cámara se balancea de lado a lado con alguna pasada ocasional."
L["Your target's frames fade until you pick a new target or land."] = "Los marcos de tu objetivo se desvanecen hasta que eliges otro objetivo o aterrizas."
L["Sway from side to side"] = "Balancearse de lado a lado"
L["The camera sways from side to side around where it started."] = "La cámara se balancea de lado a lado alrededor de donde empezó."
L["Your character does /look as a fly-by starts, which players nearby see."] = "Tu personaje hace /look al empezar una pasada, lo que ven los jugadores cercanos."
