L["Turn round"] = "Girar"
L["Turn back before landing"] = "Volver antes de aterrizar"
L["Before you land, the camera turns back to where it was at takeoff."] = "Antes de aterrizar, la cámara vuelve a donde estaba al despegar."
L["Turned back by"] = "Vuelta hecha a"
L["How long before landing the camera has settled."] = "Cuánto antes de aterrizar se ha asentado la cámara."
L["When you stand still a while or go AFK, the camera slowly circles your character."] = "Cuando estás quieto un rato o te pones ausente, la cámara da vueltas despacio alrededor de tu personaje."
L["The camera sweeps around your character, pausing between sweeps."] = "La cámara barre alrededor de tu personaje, con pausas entre barridos."
L["While you auto-run, the camera follows along until you stop or steer."] = "Mientras corres automáticamente, la cámara te acompaña hasta que pares o cambies de dirección."
L["The camera eases out a little, then drifts in and out."] = "La cámara se aleja un poco y luego se acerca y aleja."
L["When you rest, sit or dance, the camera slowly turns to face you and eases in."] = "Cuando descansas, te sientas o bailas, la cámara gira despacio para mirarte de frente y se acerca."
L["How far the camera comes down toward the ground as it turns."] = "Cuánto baja la cámara hacia el suelo al girar."
L["The camera eases in close, then drifts a little in and out."] = "La cámara se acerca y luego se acerca y aleja un poco."
L["The close-up distance the cozy camera zooms in to."] = "La distancia del primer plano al que se acerca la cámara acogedora."
L["How much lower the camera sways, to look out across the view."] = "Cuánto más baja se balancea la cámara, para mirar el paisaje."
L["The camera eases out a little, then drifts slowly in and out."] = "La cámara se aleja un poco y luego se acerca y aleja despacio."
L["The camera sways a little from side to side."] = "La cámara se balancea un poco de lado a lado."
L["How much lower the camera sways, to look out across the water."] = "Cuánto más baja se balancea la cámara, para mirar el agua."
L["When you die, the camera slowly circles your body until you release or are revived."] = "Cuando mueres, la cámara da vueltas despacio alrededor de tu cuerpo hasta que liberas el espíritu o te reviven."
L["If you die in a boss fight, the death camera waits for it to end."] = "Si mueres en un combate contra un jefe, la cámara de muerte espera a que termine."
L["No death camera when you can come back yourself, like with a soulstone."] = "Sin cámara de muerte cuando puedes volver por tu cuenta, como con una piedra de alma."
L["Adds a button under the release popup to get your own view back."] = "Añade un botón bajo la ventana de liberar espíritu para recuperar tu vista."
L["How far the camera pulls back while you're dead."] = "Cuánto se aleja la cámara mientras estás muerto."
L["How far the camera rises to look down on your body."] = "Cuánto sube la cámara para mirar tu cuerpo desde arriba."
L["The groups ticked here stay up while the death camera hides your frames."] = "Los grupos marcados aquí siguen visibles mientras la cámara de muerte oculta tus marcos."
L["Music file IDs, separated by commas; one plays at random when you die."] = "ID de archivos de música, separados por comas; al morir suena uno al azar."
L["The camera turns toward NPCs as they talk near you."] = "La cámara gira hacia los PNJ cuando hablan cerca de ti."
L["The fastest the camera swings toward a new speaker."] = "Lo más rápido que gira la cámara hacia quien empieza a hablar."
L["How far from the screen's center the speaker ends up."] = "A qué distancia del centro de la pantalla queda quien habla."
L["How far the camera drifts side to side once settled."] = "Cuánto deriva la cámara de lado a lado una vez asentada."
L["The camera turns around to find speakers you can't see."] = "La cámara se gira para encontrar a quien habla y no ves."
L["Snaps to speakers, adds a tall letterbox with subtitles and fades the whole UI."] = "Salta a quien habla, añade franjas altas con subtítulos y desvanece toda la interfaz."
L["How fast the camera zooms back out once the talking is over."] = "Qué rápido vuelve a alejarse la cámara cuando termina la conversación."
L["The longest a zoom in or out can take."] = "Lo máximo que puede tardar un acercamiento o alejamiento."
L["How long no one must talk before the camera turns back."] = "Cuánto tiempo sin que nadie hable antes de que la cámara vuelva."
L["When you talk to a quest giver, the camera zooms in and looks past you at them."] = "Cuando hablas con un PNJ de misión, la cámara se acerca y lo mira por encima de ti."
L["Also zooms in for NPCs with nothing to say about quests."] = "También se acerca con PNJ que no tienen nada que decir de misiones."
L["The camera stays put when a quest giver only has dailies or weeklies."] = "La cámara no se mueve cuando un PNJ de misión solo tiene diarias o semanales."
L["How far the camera turns to one side to look past you."] = "Cuánto gira la cámara hacia un lado para mirar por encima de ti."
L["How long the turn to the side takes."] = "Cuánto tarda el giro hacia el lado."
L["How fast the camera zooms back out once you walk away."] = "Qué rápido vuelve a alejarse la cámara cuando te marchas."
L["How far the camera comes down toward eye level."] = "Cuánto baja la cámara hacia la altura de los ojos."
L["When you cast your Hearthstone or a teleport, the camera spins around you as it zooms in."] = "Cuando lanzas tu piedra de hogar o un teletransporte, la cámara gira a tu alrededor mientras se acerca."
L["The distance the zoom ends at as the cast finishes."] = "La distancia a la que termina el zoom cuando acaba el lanzamiento."
L["Canceling"] = "Al cancelar"
L["If you cancel the cast, the camera turns back to where it was."] = "Si cancelas el lanzamiento, la cámara vuelve a donde estaba."
L["Extra settings for cameras that aren't on the Scripts page yet."] = "Ajustes extra para cámaras que aún no están en la página Guiones."
L["Mouse Turn"] = "Giro con ratón"
L["Keeps right-mouse turning smooth by capping and easing its speed."] = "Mantiene suave el giro con el botón derecho limitando y suavizando su velocidad."
L["Cap"] = "Límite"
L["Cap right-click turn speed"] = "Limitar la velocidad de giro con clic derecho"
L["Right-click turning never goes faster than the speed below."] = "El giro con clic derecho nunca va más rápido que la velocidad de abajo."
L["Top turn speed"] = "Velocidad de giro máxima"
L["The fastest you can turn."] = "Lo más rápido que puedes girar."
