L["Slow looking up and down too"] = "Frenar también al mirar arriba y abajo"
L["Looking up and down slows by the same share as turning."] = "Mirar arriba y abajo se frena en la misma proporción que girar."
L["Turns the whole Atmosphere hub on or off at once."] = "Activa o desactiva de una vez todo el centro Atmósfera."
L["How the game world looks in CineMode: vignette, inn glow, weather and depth of field."] = "El aspecto del mundo del juego en CineMode: viñeta, brillo de posada, clima y profundidad de campo."
