L["Reduce view distance in bad weather"] = "Reducir la distancia de visión con mal tiempo"
L["Brings the view distance in during rain, snow or sandstorms, more the heavier it gets."] = "Acorta la distancia de visión con lluvia, nieve o tormentas de arena, más cuanto más fuertes son."
