L["Water"] = "Agua"
L["Restart graphics"] = "Reiniciar gráficos"
L["Restarts the game's graphics without leaving the game; the screen goes black for a moment."] = "Reinicia los gráficos del juego sin salir; la pantalla se pone negra un momento."
L["Sound and music during CineMode; your own sound settings come back afterward."] = "Sonido y música durante CineMode; tus propias opciones de sonido vuelven después."
L["Plays music when a camera starts in CineMode and fades it out when the UI returns."] = "Pone música cuando empieza una cámara en CineMode y la desvanece cuando vuelve la interfaz."
