L["After a camera starts music, no camera starts it again for this long."] = "Después de que una cámara pone música, ninguna cámara la vuelve a poner durante este tiempo."
L["Fades music out once you leave the camera modes and move on."] = "Desvanece la música cuando sales de los modos de cámara y sigues tu camino."
L["Each row is a scene that plays its camera when one of its triggers happens."] = "Cada fila es una escena que reproduce su cámara cuando ocurre uno de sus activadores."
L["Lets the scenes below play their cameras when their triggers happen."] = "Permite que las escenas de abajo reproduzcan sus cámaras cuando ocurren sus activadores."
L["Auto-running in walk mode."] = "Correr automáticamente en modo andar."
L["Auto-running."] = "Correr automáticamente."
L["Dying, until you release or are resurrected."] = "Morir, hasta que liberes el espíritu o te resuciten."
L["An NPC talking to you or your party; the camera swings toward whoever's talking."] = "Un PNJ hablándote a ti o a tu grupo; la cámara gira hacia quien hable."
L["Other NPCs talking near you, once you've stood still a while."] = "Otros PNJ hablando cerca de ti, cuando llevas un rato quieto."
