L["How long you stand still before this row's camera starts."] = "Cuánto tiempo estás quieto antes de que empiece la cámara de esta fila."
L["How long the camera waits on a quest window before it starts."] = "Cuánto espera la cámara con una ventana de misión antes de empezar."
