L["Pick where chat bubbles show."] = "Elige dónde se muestran los bocadillos de chat."
L["Pick where and when each kind of bubble shows."] = "Elige dónde y cuándo se muestra cada tipo de bocadillo."
L["These bubbles show everywhere, in fights and out."] = "Estos bocadillos se muestran en todas partes, en combate y fuera de él."
L["Cinematic draws its own bubbles for speech whose game bubble you can't see."] = "Cinematic dibuja sus propios bocadillos para lo que se dice cuyo bocadillo del juego no puedes ver."
L["Shows speech from someone off screen in a bubble low on the screen."] = "Muestra lo que dice alguien fuera de pantalla en un bocadillo en la parte baja de la pantalla."
L["Opens the Chat Bubble Style page: how off-screen bubbles look and where they show."] = "Abre la página Estilo de bocadillos de chat: el aspecto de los bocadillos fuera de pantalla y dónde se muestran."
L["Shows emotes in the off-screen bubbles too, instead of in chat."] = "Muestra también los gestos en los bocadillos fuera de pantalla, en lugar de en el chat."
L["Moves bubbles at the very top of the screen down where you can read them."] = "Baja los bocadillos que quedan en lo más alto de la pantalla a donde puedas leerlos."
L["Small helpers for getting around the world."] = "Pequeñas ayudas para moverte por el mundo."
L["Turns all the Quality of Life helpers on or off."] = "Activa o desactiva todas las ayudas de Calidad de vida."
L["Opens the character window when you drag gear out of your bags."] = "Abre la ventana de personaje cuando arrastras equipo fuera de tus bolsas."
L["Adds a button to view the talents of someone you inspect."] = "Añade un botón para ver los talentos de alguien a quien inspeccionas."
L["Adds a talent calculator button to your talents window to plan a build."] = "Añade a tu ventana de talentos un botón de calculadora de talentos para planear una configuración."
L["Moves game windows away from the left edge so your character stays in view."] = "Aparta las ventanas del juego del borde izquierdo para que tu personaje siga a la vista."
L["Lets you drag the game's windows to move them."] = "Te permite arrastrar las ventanas del juego para moverlas."
