L["Show the time on those lines"] = "Mostrar la hora en esas líneas"
L["Puts the time at the start of brought-back lines."] = "Pone la hora al principio de las líneas recuperadas."
L["Show XP left to level"] = "Mostrar PX para subir de nivel"
L["Shows how much XP you still need for the next level."] = "Muestra cuántos PX te faltan para el siguiente nivel."
L["The camera zooms to the distance below when you log in or reload."] = "La cámara se pone a la distancia de abajo al conectarte o recargar."
L["The camera distance to start at."] = "La distancia de cámara con la que empezar."
L["A button at the top of the screen that reloads the UI in one click."] = "Un botón arriba de la pantalla que recarga la interfaz con un clic."
L["Reopens the windows you had open after a reload."] = "Vuelve a abrir tras recargar las ventanas que tenías abiertas."
L["Hides floating damage and healing numbers in CineMode out of combat."] = "Oculta las cifras flotantes de daño y sanación en CineMode fuera de combate."
L["Hides the red error text while you're fighting."] = "Oculta el texto rojo de error mientras combates."
L["Hides the red error text while you're out of combat."] = "Oculta el texto rojo de error mientras estás fuera de combate."
L["Turns the Hunter helpers on or off."] = "Activa o desactiva las ayudas de Cazador."
L["Right-clicking an enemy uses Auto Shot when it's far enough away."] = "Hacer clic derecho en un enemigo usa Disparo automático cuando está lo bastante lejos."
L["Moves the smallest ammo stack first after Clean Up Bags, so it's shot first."] = "Pone primero el montón de munición más pequeño tras Ordenar bolsas, para que se dispare antes."
