L["Weather on the screen"] = "El clima en la pantalla"
L["Frost creeps in on the screen's edges in snow, rain runs down the lens, and lightning flashes with thunder in storms. Off to start with: turn each up on the Weather page."] = "La escarcha cubre los bordes de la pantalla cuando nieva, la lluvia resbala por la lente y los relámpagos destellan con truenos en las tormentas. Desactivado al principio: sube cada uno en la página Clima."
L["A new rule editor"] = "Un nuevo editor de reglas"
L["The rule editor is rebuilt: words in categories you can search, suggestions as you type, and a line that shows which parts of your rule are true where you stand."] = "El editor de reglas se ha rehecho: palabras en categorías que puedes buscar, sugerencias mientras escribes y una línea que muestra qué partes de tu regla se cumplen donde estás."
L["Guidelime support"] = "Compatibilidad con Guidelime"
