-- Options.lua
L["Pick Always, < 100%, < 100% Calm or Off, or scroll over the box for other percentages."] = "Elige Siempre, < 100%, < 100% Calma o Desactivado, o usa la rueda sobre la casilla para otros porcentajes."
L["Pick Always, < 100% or Off, or scroll over the box for other percentages."] = "Elige Siempre, < 100% o Desactivado, o usa la rueda sobre la casilla para otros porcentajes."
L["Turns this page on or off, same as right-clicking its icon."] = "Activa o desactiva esta página, igual que hacer clic derecho en su icono."
L["Put this page's settings back to your profile's defaults?"] = "¿Devolver las opciones de esta página a las predeterminadas de tu perfil?"
L["Put these settings back to your profile's defaults?"] = "¿Devolver estas opciones a las predeterminadas de tu perfil?"
L["|cff808080Searching...|r"] = "|cff808080Buscando...|r"
L["Allow offscreen nameplates in CineMode"] = "Permitir placas fuera de pantalla en CineMode"
L["Keeps plates for people behind you, so Heal Vision and Emote Vision see them too."] = "Mantiene las placas de quien está detrás de ti, para que Heal Vision y la Visión de gestos también los vean."
L["Only where Heal Vision or Emote Vision use them."] = "Solo donde las usan Heal Vision o la Visión de gestos."
L["All through CineMode."] = "Durante todo CineMode."
L["Cinematic never turns them on."] = "Cinematic nunca las activa."
L["CineMode turns on by itself between fights and fades the UI."] = "CineMode se activa solo entre combates y desvanece la interfaz."
L["Walking or riding around brings the UI back."] = "Al andar o ir montado vuelve la interfaz."
L["Use a Show in row instead"] = "Usar una fila Mostrar en"
L["The row below picks where CineMode exits, in place of the boxes above."] = "La fila de abajo elige dónde se sale de CineMode, en lugar de las casillas de arriba."
L["Keeps CineMode off everywhere."] = "Mantiene CineMode desactivado en todas partes."
L["Sweeps turn the other way."] = "Los barridos giran hacia el otro lado."
L["Each time, the camera picks clockwise or counterclockwise at random."] = "Cada vez, la cámara elige al azar si gira en el sentido de las agujas del reloj o al revés."
L["Put this camera's settings back to your profile's defaults?"] = "¿Devolver las opciones de esta cámara a las predeterminadas de tu perfil?"
L["Now and then the camera turns around to look back past you."] = "De vez en cuando, la cámara se da la vuelta para mirar atrás, más allá de ti."
L["How far the camera turns around, where 180 looks straight back at you."] = "Cuánto se da la vuelta la cámara; con 180 te mira de frente."
L["How long the turn around takes, speeding up and slowing down."] = "Cuánto tarda en darse la vuelta, acelerando y frenando."
L["As you land, the camera zooms back to the zoom you had at takeoff."] = "Al aterrizar, la cámara vuelve al zoom que tenías al despegar."
L["The camera sways slowly from side to side around where it started, pausing between moves."] = "La cámara se balancea despacio de lado a lado alrededor de donde empezó, con pausas entre movimientos."
L["Once it has turned halfway around, the camera sways slowly from side to side."] = "Cuando ha dado media vuelta, la cámara se balancea despacio de lado a lado."
L["When you /stare at the view, the camera sways very slightly from where it is."] = "Cuando contemplas el paisaje con /stare, la cámara se balancea muy poco desde donde está."
L["The camera sways very slightly from side to side."] = "La cámara se balancea muy poco de lado a lado."
L["While you fish, the camera sways a little and keeps your bobber in view."] = "Mientras pescas, la cámara se balancea un poco y no pierde de vista tu corcho."
L["While you auto-walk, the camera drifts slowly along with you."] = "Mientras andas con avance automático, la cámara se desliza despacio contigo."
L["Each death, the camera picks clockwise or counterclockwise at random."] = "En cada muerte, la cámara elige al azar si gira en el sentido de las agujas del reloj o al revés."
L["The camera zooms in to this distance if you're farther out."] = "La cámara se acerca hasta esta distancia si estás más lejos."
L["Which side of you the camera moves to."] = "A qué lado tuyo se mueve la cámara."
L["The camera turns to the side as it zooms in, then tilts down."] = "La cámara gira hacia un lado mientras se acerca y luego se inclina hacia abajo."
L["How fast the spin speeds up after the first half turn."] = "Lo rápido que acelera el giro tras la primera media vuelta."
L["As it turns, the camera also drops toward the ground. Negative values raise it instead."] = "Mientras gira, la cámara también baja hacia el suelo. Con valores negativos, sube."
L["The camera starts zooming in when the cast starts, and is still zooming in as you leave."] = "La cámara empieza a acercarse al empezar el lanzamiento, y sigue acercándose cuando te vas."
L["How fast the camera zooms back out to your own distance if you cancel the cast."] = "Lo rápido que la cámara vuelve a tu distancia si cancelas el lanzamiento."
L["Load Atmosphere"] = "Cargar Atmósfera"
L["Unticked, Atmosphere doesn't load at all (takes a reload)."] = "Desmarcado, Atmósfera no se carga en absoluto (hay que recargar)."
L["Tick it and reload to bring every Atmosphere page back."] = "Márcalo y recarga para recuperar todas las páginas de Atmósfera."
L["Turn off to keep Atmosphere from loading at all."] = "Desactívalo para que Atmósfera no se cargue en absoluto."
L["Atmosphere isn't loaded: no tint, letterbox, haze, Graphics Boost or music runs, and their pages are gone."] = "Atmósfera no está cargada: no funcionan el tinte, las franjas, la neblina, Graphics+ ni la música, y sus páginas no están."
L["How the game world looks in CineMode: vignette, inn glow and depth of field."] = "El aspecto del mundo del juego en CineMode: viñeta, brillo de posada y profundidad de campo."
L["Haze"] = "Neblina"
L["Darkens the edges of the screen."] = "Oscurece los bordes de la pantalla."
L["Shows the vignette for a few seconds, in CineMode or not."] = "Muestra la viñeta unos segundos, en CineMode o no."
L["A warm firelight glow, brightest low on the screen."] = "Un brillo cálido de hoguera, más fuerte en la parte baja de la pantalla."
L["Shows the glow for a few seconds, in CineMode or not."] = "Muestra el brillo unos segundos, en CineMode o no."
L["Haze strength"] = "Fuerza de la neblina"
L["A light haze around the edges of the screen."] = "Una neblina suave en los bordes de la pantalla."
L["Shows the haze at this strength for a few seconds, in CineMode or not."] = "Muestra la neblina con esta fuerza unos segundos, en CineMode o no."
L["How they look"] = "Su aspecto"
L["Style pages:"] = "Páginas de Estilo:"
L["The tint's preset, time of day and zone moods."] = "El preajuste del tinte, la hora del día y el ambiente de las zonas."
L["Each weather's color, and how fast it comes in."] = "El color de cada clima y lo rápido que llega."
L["Music can play any time in CineMode, so the other columns don't matter."] = "La música puede sonar en cualquier momento de CineMode, así que las demás columnas no importan."
L["Load Cameras"] = "Cargar cámaras"
L["Unticked, Cinematic's cameras don't load at all (takes a reload)."] = "Desmarcado, las cámaras de Cinematic no se cargan en absoluto (hay que recargar)."
L["Tick it and reload to bring every camera back."] = "Márcalo y recarga para recuperar todas las cámaras."
L["Turn off to keep the cameras from loading at all."] = "Desactívalo para que las cámaras no se carguen en absoluto."
L["Cameras aren't loaded: none of them run, and their pages are gone."] = "Las cámaras no están cargadas: no funciona ninguna y sus páginas no están."
L["In CineMode, the camera moves on its own when things happen, like emotes, flights or going AFK."] = "En CineMode, la cámara se mueve sola cuando pasan cosas, como emociones, vuelos o ponerte ausente."
L["Move this row up so its trigger tries it sooner."] = "Sube esta fila para que su activador la pruebe antes."
L["Move this row down so its trigger tries it later."] = "Baja esta fila para que su activador la pruebe después."
L["Uses this row. Untick it and its trigger skips it."] = "Usa esta fila. Desmárcala y su activador se la salta."
L["Turns this section on or off. When it's off, CineMode leaves its frames alone."] = "Activa o desactiva esta sección. Si está desactivada, CineMode no toca sus marcos."
L["CineMode hides the range hint: pick when it shows."] = "CineMode oculta el aviso de alcance: elige cuándo se muestra."
L["When the XP bar, bags, micro menu and similar frames show."] = "Cuándo se muestran la barra de experiencia, las bolsas, el micromenú y marcos parecidos."
L["How the damage and healing numbers over heads look."] = "El aspecto de los números de daño y sanación sobre las cabezas."
L["Shows chat bubbles where this page says. When it's off, the game's own settings are used."] = "Muestra los bocadillos de chat donde diga esta página. Si está desactivada, se usan las opciones del juego."
L["Windows"] = "Ventanas"
L["Open windows clear of your character"] = "Abrir ventanas sin tapar al personaje"
L["Dead center instead"] = "Justo en el centro"
L["Opens them in the very middle of the screen."] = "Las abre justo en el centro de la pantalla."
L["Forget where you dragged the windows, so each opens in its usual place again."] = "Olvida dónde arrastraste las ventanas, para que cada una vuelva a abrirse en su sitio de siempre."
L["Dressing room beside the Auction House"] = "Probador junto a la casa de subastas"
L["Ctrl+Click an auction to see it on you without the Auction House closing."] = "Haz Ctrl+clic en una subasta para verla puesta sin que se cierre la casa de subastas."
L["Gear and talents"] = "Equipo y talentos"
L["Off by default because it can cause harmless errors in error-catching addons."] = "Desactivado por defecto porque puede causar errores inofensivos en addons que capturan errores."
L["Login and reload"] = "Al entrar y recargar"
L["Open the AddOns list on All"] = "Abrir la lista de accesorios en Todos"
L["The game's AddOns list starts on All instead of just this character."] = "La lista de accesorios del juego empieza en Todos en vez de solo este personaje."
L["Text on screen"] = "Texto en pantalla"
L["Cast and reel in with the mouse or a gamepad, in CineMode or not."] = "Lanza y recoge el sedal con el ratón o un mando, en CineMode o no."
L["The game's sound effects volume while you fish. The splash of a bite is a sound effect."] = "El volumen de efectos de sonido del juego mientras pescas. El chapoteo de un pez que pica es un efecto de sonido."
L["Show in fights, and after them until the Calm Timer runs out."] = "Se muestra en combate, y después hasta que se agote el Temporizador de calma."
