L["Show out in the world, inns included. Capital cities count as Cities."] = "Se muestra en el mundo, posadas incluidas. Las capitales cuentan como Ciudades."
L["Enemies in ~30 yd"] = "Enemigos a ~30 m"
L[" The nameplate of the unit under your mouse, whatever the Nameplates grid says."] = " La placa de nombre de la unidad bajo tu ratón, diga lo que diga la tabla de Placas de nombre."
L[" Hostile NPCs and enemy players within about 30 yards (your spell nearest 30 yards), whatever their rows say."] = " PNJ hostiles y jugadores enemigos a unos 30 metros (tu hechizo más cercano a 30 metros), digan lo que digan sus filas."
