L[" Every other names row shows only where this one does."] = " Las demás filas de nombres solo se muestran donde se muestre esta."
L["Names look as this page says. When it's off, they look the way the nameplate draws them."] = "Los nombres se ven como diga esta página. Si está desactivada, se ven como los dibuja la placa."
L["Every plate that no row above fits."] = "Todas las placas que no encajan en ninguna fila de arriba."
L["How every nameplate looks: its bar, its name and its parts."] = "El aspecto de cada placa de nombre: su barra, su nombre y sus partes."
L["Turns the nameplates' look on or off, Smart, Cast Bars and Layout with it."] = "Activa o desactiva el aspecto de las placas de nombre, y con él Inteligente, Barras de lanzamiento y Disposición."
