L["Limits this row to the neutral ones among them."] = "Limita esta fila a los neutrales de entre ellos."
L["Limits this row to the friendly ones among them."] = "Limita esta fila a los amistosos de entre ellos."
L["Only hostile NPCs roughly close enough to attack you."] = "Solo PNJ hostiles lo bastante cerca como para atacarte, más o menos."
L["Only units roughly that far from you."] = "Solo unidades a más o menos esa distancia de ti."
L["Within ~30 yd"] = "A menos de ~30 m"
L["Past ~30 yd"] = "A más de ~30 m"
L["Within %d yards"] = "A menos de %d metros"
L["Past %d yards"] = "A más de %d metros"
L["in ~30 yd"] = "a ~30 m"
L["past ~30 yd"] = "+~30 m"
L["in %d yd"] = "a %d m"
L["past %d yd"] = "+%d m"
L["Any enemy attacking whoever is ticked."] = "Cualquier enemigo que ataque a quien esté marcado."
L["Limits this row to these among them: %s."] = "Limita esta fila a estos de entre ellos: %s."
L["Drag to move this row. A plate tries the rows from the top down."] = "Arrastra para mover esta fila. Una placa prueba las filas de arriba abajo."
L["Tick Enemy, Neutral or Friendly to limit this row to those. Tick all three for any."] = "Marca Enemigos, Neutral o Amistosos para limitar esta fila a esos. Marca los tres para cualquiera."
L["can't measure"] = "no se puede medir"
L["Nothing on this character measures distance."] = "Nada de este personaje mide la distancia."
L["Measured with %s (%d yards)."] = "Medido con %s (%d metros)."
L["In fights: %s (%d yards)."] = "En combate: %s (%d metros)."
L["In fights nothing measures it."] = "En combate no hay nada que la mida."
L["Pop out: this row's preview in a window of its own."] = "Sacar: la vista previa de esta fila en una ventana propia."
L["This row's own look on its plates, in the Style Studio."] = "El aspecto propio de esta fila en sus placas, en el Estudio de Estilo."
L["Tick the parts of the plate that get its color."] = "Marca las partes de la placa que llevan su color."
L["Its messages show chat out in the world, inns included. Capital cities count as Cities."] = "Sus mensajes muestran el chat en el mundo, posadas incluidas. Las capitales cuentan como Ciudades."
L["When a new message shows chat, and which parts of the chat window come up with it."] = "Cuándo un mensaje nuevo muestra el chat, y qué partes de la ventana de chat aparecen con él."
L["Pressing Enter brings up the chat window where ticked, and just the input box elsewhere."] = "Pulsar Intro muestra la ventana de chat donde esté marcado, y solo la casilla de escritura en los demás sitios."
L["Typing brings up the chat window any time, so the other columns don't matter."] = "Al escribir aparece la ventana de chat siempre, así que las demás columnas no importan."
L["Where and when the minimap stays up the whole time."] = "Dónde y cuándo el minimapa se queda a la vista todo el rato."
L["Shows the minimap while the spot to hand in a finished quest is on it."] = "Muestra el minimapa mientras en él está el sitio donde entregar una misión terminada."
L["Map pin"] = "Marca del mapa"
L["Shows the minimap while your map pin is on it."] = "Muestra el minimapa mientras tu marca del mapa está en él."
L["Not for Shortest Path"] = "No con Shortest Path"
L["Shortest Path Forever's journey pin doesn't show the minimap."] = "La marca de viaje de Shortest Path Forever no muestra el minimapa."
L["How long the minimap stays up after quest progress. Set to Off to keep it up."] = "Cuánto tiempo sigue a la vista el minimapa tras avanzar en una misión. Ponlo en Desactivado para dejarlo siempre."
L["Takes effect after a reload."] = "Se aplica tras recargar."
L["Load Style"] = "Cargar Estilo"
L["Unticked, Style doesn't load at all (takes a reload)."] = "Desmarcado, Estilo no se carga en absoluto (hay que recargar)."
L["Tick it and reload to bring every Style page back."] = "Márcalo y recarga para recuperar todas las páginas de Estilo."
L["Turn off to keep Style from loading at all."] = "Desactívalo para que Estilo no se cargue en absoluto."
L["load Style"] = "cargar Estilo"
L["leave Style out"] = "dejar fuera Estilo"
L["Visions aren't loaded: none of them run, and their pages are gone."] = "Las visiones no están cargadas: no funciona ninguna y sus páginas no están."
L["Load Visions"] = "Cargar visiones"
L["Unticked, Visions don't load at all (takes a reload)."] = "Desmarcado, las visiones no se cargan en absoluto (hay que recargar)."
L["Tick it and reload to bring every Vision back."] = "Márcalo y recarga para recuperar todas las visiones."
L["Turn off to keep Visions from loading at all."] = "Desactívalo para que las visiones no se carguen en absoluto."
L["Range Hint"] = "Aviso de alcance"
L["Turns the range hint on or off."] = "Activa o desactiva el aviso de alcance."
L["Which spell's range it checks."] = "El alcance de qué hechizo comprueba."
L["Spell for %s"] = "Hechizo para %s"
L["The mark shows while your target is out of this spell's range. Auto uses the longest-range attack on your bars."] = "La marca se muestra mientras tu objetivo está fuera del alcance de este hechizo. Automático usa el ataque de mayor alcance de tus barras."
L["Move it in Edit Mode."] = "Muévelo en el Modo Edición."
L["Close CDM"] = "Cerrar CDM"
L["Closes the game's own Cooldown Manager settings."] = "Cierra las opciones del Gestor de reutilización del juego."
L["Essentials"] = "Esenciales"
L["Set here but never takes effect:"] = "Puesto aquí, pero nunca se aplica:"
L["%s in %s (no locations yet)"] = "%s en %s (aún sin lugares)"
L["%s in %s (never applies)"] = "%s en %s (nunca se aplica)"
L["Spells with Flash set flash as their cooldown ends. Off: none do."] = "Los hechizos con Destello destellan cuando acaba su reutilización. Desactivado: ninguno lo hace."
L["The icon grows a little and shrinks back with each beat while it flashes."] = "El icono crece un poco y vuelve a encogerse con cada latido mientras destella."
L[" You can change its look on the Quest Item Button tab."] = " Puedes cambiar su aspecto en la pestaña Botón del objeto de misión."
L["Works in"] = "Funciona en"
L["On in fights, and after them until the Calm Timer runs out."] = "Activado en combate, y después hasta que se agote el Temporizador de calma."
L["On while you're in any of these. Party and Raid count anywhere, as long as you're in one."] = "Activado mientras estés en cualquiera de estos. Grupo y Banda cuentan en cualquier sitio, siempre que estés en uno."
L["These settings apply to every role that uses the default settings."] = "Estas opciones se aplican a todos los roles que usan las opciones predeterminadas."
L["How much of a dead member still shows."] = "Cuánto se sigue viendo de un miembro muerto."
L["Hidden members still show their aura icons and dispel glow."] = "Los miembros ocultos siguen mostrando sus iconos de auras y el brillo de disipar."
L["Show health on names"] = "Mostrar la salud en los nombres"
L["Names grey out as health is lost, like a health bar."] = "Los nombres se vuelven grises a medida que se pierde salud, como una barra de salud."
L["Tooltips show the whole time in CineMode, so the other columns don't matter."] = "Los tooltips se muestran todo el rato en CineMode, así que las demás columnas no importan."
L["The zone under a party member's class when they're out of sight (\"Stormwind City\")."] = "La zona bajo la clase de un miembro del grupo cuando no está a la vista (\"Ventormenta\")."
L["Faction and PvP (yours)"] = "Facción y JcJ (la tuya)"
L["The Horde or Alliance and PvP lines of your own faction."] = "Las líneas de Horda o Alianza y JcJ de tu propia facción."
L["Faction and PvP (enemies)"] = "Facción y JcJ (enemigos)"
L["The Horde or Alliance and PvP lines of the other faction."] = "Las líneas de Horda o Alianza y JcJ de la otra facción."
L["CineMode hides these addons' frames. Pick which ones show, and when."] = "CineMode oculta los marcos de estos addons. Elige cuáles se muestran, y cuándo."
L["Addons you install later always show in CineMode to start with."] = "Los addons que instales después se muestran siempre en CineMode al principio."
L["Does what Load does for every frame on this list that isn't loaded yet."] = "Hace lo mismo que Cargar con cada marco de esta lista que aún no esté cargado."
L["Frames you've shown or hidden with their keys below go back to what their Show in row says."] = "Los marcos que hayas mostrado u ocultado con sus teclas de abajo vuelven a lo que diga su fila Mostrar en."
L["Cinematic's page comes up when the fight ends"] = "La página de Cinematic aparece cuando acaba el combate"
L["Put the profile %s back to how it started? Every change you've made to it will be lost."] = "¿Devolver el perfil %s a como empezó? Perderás todos los cambios que le hayas hecho."
L["Put the profile %s back to how you last saved it? Changes you've made since then will be lost."] = "¿Devolver el perfil %s a como lo guardaste por última vez? Perderás los cambios que hayas hecho desde entonces."
L["Pointing at a faded frame shows it, along with the other frames in its groups."] = "Al señalar un marco desvanecido, se muestra junto con los demás marcos de sus grupos."
L["Right-click to go back to its own icon."] = "Haz clic derecho para volver a su propio icono."
L["Floating text changes after you log out and back in (/reload isn't enough). The same goes for getting it back: until you log out it stays hidden, even with Cinematic turned off."] = "El texto flotante cambia cuando sales y vuelves a entrar (/reload no basta). Lo mismo para recuperarlo: hasta que salgas sigue oculto, aunque desactives Cinematic."
L["Style isn't loaded: no Style page or look runs, and their pages are gone."] = "Estilo no está cargado: no funciona ninguna página ni aspecto de Estilo, y sus páginas no están."

-- ProfilerPage.lua
L["It's off. Right-click the Profiler icon to start sampling."] = "Está desactivado. Haz clic derecho en el icono del Perfilador para empezar a medir."
L["What the game measured for Cinematic over the same time, including what the timers don't cover."] = "Lo que el juego midió para Cinematic en el mismo tiempo, incluido lo que los temporizadores no cubren."
L["Memory used and thrown away each second. The game spends time cleaning it up."] = "Memoria usada y desechada cada segundo. El juego pierde tiempo en limpiarla."
L["(Called by the part above, so its time is counted in that one.)"] = "(La llama la parte de arriba, así que su tiempo se cuenta en esa.)"

-- RuleAxes.lua
L["open now"] = "abierta ahora"

-- Slash.lua
L["the camera turns once around you: 360 degrees over 10 seconds unless you give a number (a negative one turns the other way); again stops it"] = "la cámara da una vuelta a tu alrededor: 360 grados en 10 segundos salvo que pongas un número (uno negativo gira al revés); otra vez la detiene"
L["show or hide the keyboard map: what each of your keys does (add words to find them on it)"] = "muestra u oculta el mapa del teclado: lo que hace cada tecla (añade palabras para buscarlas en él)"
L["fade the frame you're hovering over too (or /cine add <FrameName>)"] = "desvanece también el marco que tienes bajo el ratón (o /cine add <NombreDelMarco>)"
L["your damage report for this run: boss by boss, the rest, the whole party (test shows a made-up one)"] = "tu informe de daño de esta partida: jefe a jefe, el resto y todo el grupo (test muestra uno inventado)"
L["record what the addon costs, results on the Profiler page (add deep for more detail, or stop to end it early)"] = "mide lo que cuesta el addon, con los resultados en la página Perfilador (añade deep para más detalle, o stop para acabar antes)"
L["%d matches for \"%s\", best: \"%s\" (%s). Pick one in the results window."] = "%d resultados para \"%s\", el mejor: \"%s\" (%s). Elige uno en la ventana de resultados."
