L["letterbox bars: the Letterbox page is off"] = "franjas: la página Franjas está desactivada"

-- Atmosphere/LowHealth.lua
L["That isn't the whole thing. Copy it again, all of it."] = "Eso no está completo. Cópialo otra vez, entero."
L["At what health the edges close in, and how fast."] = "Con cuánta salud se cierran los bordes, y lo rápido que lo hacen."
L["The color of a big hit's flash, and the color the world fades to."] = "El color del destello de un golpe fuerte, y el color al que se apaga el mundo."
L["This theme's heartbeat speed, relative to Beats a minute above. A creeping theme beats slower."] = "La velocidad del latido de este tema, en relación con Latidos por minuto de arriba. Un tema lento late más despacio."
L["How much this theme throbs, relative to Throb above."] = "Cuánto palpita este tema, en relación con Pulso de arriba."
L["The theme's art that spreads in from the edges."] = "El dibujo del tema que se extiende desde los bordes."
L["The glow around the art, added as light. This is Glow's only color."] = "El brillo alrededor del dibujo, sumado como luz. Es el único color de Brillo."
L["How strong the glow is compared to the art."] = "Lo fuerte que es el brillo comparado con el dibujo."
L["The theme's art (blood, smoke, a glow) that spreads in from the edges as they close in."] = "El dibujo del tema (sangre, humo, un brillo) que se extiende desde los bordes mientras se cierran."
L["How many appear per minute at full strength. A big hit adds a few more."] = "Cuántos aparecen por minuto a plena fuerza. Un golpe fuerte añade unos pocos más."
L["How big they are compared to normal."] = "Lo grandes que son comparados con lo normal."
L["How strong it is at full, multiplied by the art's opacity."] = "Lo fuerte que es al máximo, multiplicado por la opacidad del dibujo."
L["Overall strength, reach and brightness, plus the shadow, the heartbeat and big hits."] = "Fuerza, alcance y brillo generales, además de la sombra, el latido y los golpes fuertes."
L["How the screen looks as your mana runs out."] = "El aspecto de la pantalla cuando te quedas sin maná."
L["As your health drops, the edges of the screen close in."] = "Cuando baja tu salud, los bordes de la pantalla se cierran."
L["Shows everywhere, so the other columns don't change anything."] = "Se muestra en todas partes, así que las demás columnas no cambian nada."
L["The edges start closing in when your health drops below this."] = "Los bordes empiezan a cerrarse cuando tu salud baja de esto."
L["The edges are all the way in when your health drops to this. Keep it below Starts."] = "Los bordes se cierran del todo cuando tu salud baja hasta esto. Déjalo por debajo de Empieza."
L["How much of your health one hit has to take to count as a big hit."] = "Cuánta salud tiene que quitarte un golpe para contar como golpe fuerte."
L["As your mana runs out, the screen drains. Right-click the tab to turn it on."] = "Cuando te quedas sin maná, la pantalla pierde color. Haz clic derecho en la pestaña para activarlo."

-- Atmosphere/ManaVision.lua
L["Low mana"] = "Poco maná"
L["The screen starts to drain when your mana drops below this."] = "La pantalla empieza a perder color cuando tu maná baja de esto."
L["The screen is fully drained when your mana drops to this. Keep it below Starts."] = "La pantalla pierde todo el color cuando tu maná baja hasta esto. Déjalo por debajo de Empieza."
L["How strong it is out of a fight."] = "Lo fuerte que es fuera de combate."
L["Shows your mana running out on the screen."] = "Muestra en la pantalla cómo te quedas sin maná."
L["This character doesn't use mana, so nothing shows."] = "Este personaje no usa maná, así que no se muestra nada."
L["Drained"] = "Sin color"
L["Gray-blue: the world's color drains away."] = "Gris azulado: el mundo pierde su color."
L["Cold"] = "Frío"
L["A cold, deep blue."] = "Un azul frío y profundo."
L["A dim, gray-violet dusk."] = "Un anochecer apagado, gris violáceo."
L["How strong the veil and the edges are when your mana is out."] = "Lo fuertes que son el velo y los bordes cuando no te queda maná."
L["Dark edges"] = "Bordes oscuros"
L["Dark edges close in as your mana runs out."] = "Unos bordes oscuros se cierran cuando te quedas sin maná."
L["How far in from the screen's edges they come."] = "Hasta dónde entran desde los bordes de la pantalla."
L["Shows your mana running out in the preview and on screen."] = "Muestra cómo te quedas sin maná en la vista previa y en pantalla."

-- Atmosphere/TeleportVision.lua
L["Motes in the portal's color drift in from the rim."] = "Motas del color del portal entran flotando desde el borde."
L["Plays a pretend 8-second cast on screen. Close the settings to see it."] = "Muestra en pantalla un lanzamiento de prueba de 8 segundos. Cierra las opciones para verlo."

-- Atmosphere/Tint.lua
L["Warm brownish yellow, like an old photo. The world can't be fully desaturated."] = "Amarillo pardo cálido, como una foto antigua. El mundo no puede quedarse del todo sin color."
L["A warm haze over everything."] = "Una neblina cálida sobre todo."

-- Camera/CameraManager.lua
L["Right-click to copy it, or to rename, describe, change the icon of or delete one of yours."] = "Haz clic derecho para copiarla, o para renombrar, describir, cambiar el icono o borrar una de las tuyas."
L["Makes a copy of this camera's script for you to change, and opens its tab."] = "Hace una copia del guion de esta cámara para que la cambies, y abre su pestaña."

-- Camera/CameraScriptsPage.lua
L["Runs when the camera ends, whatever ends it (its stop rules say what does). Every camera has one and it can't be removed. Pick it and add steps to put them inside."] = "Se ejecuta cuando acaba la cámara, sea lo que sea lo que la acabe (sus reglas de parada dicen qué). Toda cámara tiene uno y no se puede quitar. Elígelo y añade pasos para meterlos dentro."
L["Lets scenes play your scripts, and lets our cameras use your changes to their scripts."] = "Deja que las escenas reproduzcan tus guiones, y que nuestras cámaras usen tus cambios en sus guiones."
L["This script as text to share with friends."] = "Este guion como texto para compartirlo con amigos."
L["A haze around the edges of the screen while this camera runs. Set to 0 to turn it off."] = "Una neblina en los bordes de la pantalla mientras funciona esta cámara. Ponlo en 0 para quitarla."
L["A built-in camera you've changed. Reset puts ours back."] = "Una cámara integrada que has cambiado. Restablecer devuelve la nuestra."
L["A built-in camera, made from your settings. Any change you make saves it as your own."] = "Una cámara integrada, hecha con tus opciones. Cualquier cambio que hagas la guarda como tuya."

-- Camera/CameraTriggerEditor.lua
L["Another trigger for this scene. Any one of its triggers starts it."] = "Otro activador para esta escena. Cualquiera de sus activadores la inicia."
L["Turns CineMode on while its camera runs, if Start in CineMode is off."] = "Activa CineMode mientras funciona su cámara, si Empezar en CineMode está desactivado."

-- Camera/ShotsPage.lua
L["Copies text you can send a friend, who adds this shot with Import here or on their Scenes page."] = "Copia un texto que puedes mandar a un amigo, que añade este plano con Importar aquí o en su página Escenas."
L["The camera whose moves this shot uses."] = "La cámara cuyos movimientos usa este plano."
L["Clears this shot's numbers so they go back to its camera's own settings."] = "Borra los números de este plano para que vuelvan a las opciones de su cámara."

-- Camera/ShoulderCalibrate.lua
L["Stops using this measurement and goes back to the built-in size."] = "Deja de usar esta medida y vuelve al tamaño integrado."

-- Camera/ShoulderCam.lua
L["Another addon (DynamicCam) is running a shoulder camera, so the Shoulder Cam stays off."] = "Otro addon (DynamicCam) ya usa una cámara al hombro, así que la Cámara al hombro sigue desactivada."
L["Shoulder Cam uses some experimental Blizzard features, as well as some hacks to fill in the gaps."] = "La Cámara al hombro usa algunas funciones experimentales de Blizzard, y algunos apaños para cubrir lo que falta."
L["Which frames slide with you while the camera is over your shoulder."] = "Qué marcos se desplazan contigo mientras la cámara está sobre tu hombro."
L["Which of Cinematic's cameras keep the Shoulder Cam on while they play."] = "Qué cámaras de Cinematic mantienen la Cámara al hombro activada mientras funcionan."
L["Over your shoulder everywhere, so the other columns don't matter."] = "Sobre tu hombro en todas partes, así que las demás columnas no importan."
L["How far from the middle you sit when zoomed out. Set it lower than Spot on screen to keep the camera from catching on walls, which only happens zoomed out."] = "Lo lejos del centro que quedas con el zoom alejado. Ponlo más bajo que Lugar en pantalla para que la cámara no se enganche en las paredes, algo que solo pasa con el zoom alejado."
L["The camera distance where you reach Spot zoomed out. Between 5 yards and this distance, you slide from Spot on screen to Spot zoomed out."] = "La distancia de cámara a la que llegas a Lugar con zoom alejado. Entre 5 metros y esta distancia, pasas poco a poco de Lugar en pantalla a Lugar con zoom alejado."
L["Keep the shoulder when selecting yourself"] = "Seguir al hombro al seleccionarte"
L["Selecting yourself clears your target instead, so the camera stays over your shoulder. Heals and buffs still land on you."] = "Seleccionarte a ti mismo quita tu objetivo, así la cámara sigue sobre tu hombro. Las sanaciones y beneficios te siguen llegando."
L["Shows our own copy of your target frame, so it matches only the game's look or a Cinematic theme."] = "Muestra nuestra propia copia de tu marco de objetivo, para que solo siga el aspecto del juego o un tema de Cinematic."
L["How long the Shoulder Cam waits to come back over your shoulder after you step outside or get off your mount. Going back in or mounting again during the wait starts it over."] = "Cuánto espera la Cámara al hombro para volver sobre tu hombro tras salir al exterior o bajarte de la montura. Si vuelves a entrar o a montar durante la espera, empieza de nuevo."
L["Turns to who you talk to everywhere, so the other columns don't matter."] = "Se gira hacia con quien hablas en todas partes, así que las demás columnas no importan."
L["How many seconds the camera takes to move behind you for this camera. Leave it empty to use %s."] = "Cuántos segundos tarda la cámara en ponerse detrás de ti con esta cámara. Déjalo vacío para usar %s."

-- Camera/SkyrideCam.lua
L["Everywhere you skyride, so the other columns don't matter."] = "Donde sea que surques los cielos, así que las demás columnas no importan."
L["How far past your cruise distance (set in Take off) the camera goes."] = "Cuánto se aleja la cámara más allá de tu distancia de crucero (fijada en Despegue)."
L["At 0.5 it's a snap, as fast as the game's zoom can go."] = "Con 0.5 es instantáneo, tan rápido como permite el zoom del juego."
L["How close the camera comes in. Set to 0 to keep its distance."] = "Cuánto se acerca la cámara. Ponlo en 0 para que mantenga su distancia."
L["Second Wind brings the camera in a little, then back out."] = "Segundo aliento acerca un poco la cámara y luego la vuelve a alejar."
L["The fastest the camera can move. Moves that would go faster take longer instead."] = "Lo más rápido que puede moverse la cámara. Los movimientos que irían más rápido tardan más."
L["Blends one move into the next. At 0 the camera stops between moves."] = "Funde un movimiento con el siguiente. Con 0, la cámara se para entre movimientos."

-- Camera/TriggersPage.lua
L["For now, its camera follows its own rules for when it plays."] = "Por ahora, su cámara sigue sus propias reglas sobre cuándo funciona."
L["Moves it up, so it wins over the one above."] = "Lo sube, para que gane al de arriba."
L["Moves it down, so the one below wins over it."] = "Lo baja, para que el de abajo le gane."
L["Makes a copy of this trigger that you can change on its own."] = "Hace una copia de este activador que puedes cambiar por separado."
L["Puts its Only if, wait, cooldown, chance and priority back to how they came."] = "Devuelve su Solo si, espera, recarga, probabilidad y prioridad a como venían."
L["A wait before it starts, a minimum time, a cooldown and a chance."] = "Una espera antes de empezar, un tiempo mínimo, una recarga y una probabilidad."
L["A rule that must be true for it to start. Leave it empty to always start. Click to edit."] = "Una regla que debe cumplirse para que empiece. Déjala vacía para que empiece siempre. Haz clic para editarla."
L["When on, it waits until its condition is no longer true before it can start again."] = "Si está activado, espera a que su condición deje de cumplirse antes de poder empezar otra vez."

