-- Style/CdmStyle.lua
L["After a few hits"] = "Tras unos golpes"
L["Draining"] = "Vaciándose"
L["Just cast"] = "Recién lanzado"
L["Halfway"] = "A medias"
L["Cooldown Manager Style"] = "Estilo del Gestor de reutilización"
L["How the drain ring on your tracked buffs looks. Pick which buffs get one on the Cooldown Manager page, under Look."] = "El aspecto del anillo que se vacía en tus beneficios seguidos. Elige qué beneficios lo llevan en la página Gestor de reutilización, en Aspecto."
L["Turns this page's ring look on or off. Off: the ring's own look."] = "Activa o desactiva el aspecto del anillo de esta página. Desactivado: el aspecto propio del anillo."
L["How the drain ring on your tracked buffs looks."] = "El aspecto del anillo que se vacía en tus beneficios seguidos."
L["The Cooldown Manager icons' shape."] = "La forma de los iconos del Gestor de reutilización."
L["Cooldown + DoT"] = "Reutilización + DoT"
L["How a spell's cooldown shows over its DoT, on rows whose Shows is Both."] = "Cómo se muestra la reutilización de un hechizo sobre su DoT, en las filas con Muestra en Ambos."
