L["Square icons, whatever the action buttons are."] = "Iconos cuadrados, sean como sean los botones de acción."
L["Round icons, whatever the action buttons are."] = "Iconos redondos, sean como sean los botones de acción."
L["Pips"] = "Puntos"
L["Eight chunky segments round the icon."] = "Ocho segmentos gruesos alrededor del icono."
L["One thin ring round the icon."] = "Un anillo fino alrededor del icono."
L["Liquid"] = "Líquido"
L["The icon empties from the top down."] = "El icono se vacía de arriba abajo."
L["Bar under"] = "Barra debajo"
L["A thin bar under the icon."] = "Una barra fina bajo el icono."
L["How big the ring is next to the icon."] = "El tamaño del anillo respecto al icono."
L["Empty part"] = "Parte vacía"
L["How dark the spent part shows. 0: hidden."] = "Lo oscura que se ve la parte gastada. 0: oculta."
L["The ring in your class's color."] = "El anillo del color de tu clase."
L["From the full end's color to the empty end's: what's left turns toward the empty color as it drains."] = "Del color del extremo lleno al del vacío: lo que queda va tomando el color vacío según se gasta."
L["The color you pick below."] = "El color que elijas abajo."
L["A plain white ring."] = "Un anillo blanco sin más."
