L["Empty end"] = "Extremo vacío"
L["The gradient's color where the shield runs out."] = "El color del degradado donde el escudo se acaba."
L["Left / right"] = "Izquierda / derecha"
L["Moves the amount left or right from the icon's middle."] = "Mueve la cantidad a la izquierda o a la derecha del centro del icono."
L["Down / up"] = "Abajo / arriba"
L["Moves the amount down or up from the icon's middle."] = "Mueve la cantidad hacia abajo o arriba del centro del icono."
L["How big the amount's text is."] = "El tamaño del texto de la cantidad."
L["Which buffs get a ring, and the game's timer: the Cooldown Manager page, under Look."] = "Qué beneficios llevan anillo, y el temporizador del juego: en la página Gestor de reutilización, en Aspecto."
