-- Style/CombatTextPage.lua
L["You may see other people's damage as your own."] = "Puede que veas el daño de otros como si fuera tuyo."
L["Each text starts out looking like the one it's under. Changing one only changes that one."] = "Cada texto empieza con el aspecto del que tiene encima. Cambiar uno solo cambia ese."
L["Spells"] = "Hechizos"
L["A look of their own for any of your spells."] = "Un aspecto propio para cualquiera de tus hechizos."
L["Ours look the way the Look tab sets them. The game's look as they always do."] = "Los nuestros se ven como dice la pestaña Aspecto. Los del juego, como siempre."
L["The game's own numbers, the way it normally draws them."] = "Los números del propio juego, como los dibuja siempre."
L["Set XP and other floating text to The game's first. While it's on None, the game draws none of its numbers."] = "Pon primero PX y otro texto flotante en La del juego. Mientras esté en Ninguno, el juego no dibuja ninguno de sus números."
L["Ours when you're solo. In a group or raid, the game's own, which show every pet hit."] = "El nuestro cuando vas solo. En grupo o banda, el del juego, que muestra cada golpe de la mascota."
L["In a group, ours only show your pet's spells, since its swings look the same as everyone else's. The game's shows every pet hit in its own look."] = "En grupo, el nuestro solo muestra los hechizos de tu mascota, porque sus golpes normales son iguales que los de los demás. La del juego muestra cada golpe de la mascota con su propio aspecto."
L["Hides all the game's floating text, damage numbers included. Log out and back in to apply."] = "Oculta todo el texto flotante del juego, números de daño incluidos. Sal y vuelve a entrar para aplicarlo."
L["Log out and back in to apply. With it hidden the game draws none of its numbers, so The game's is grayed out in the rows above."] = "Sal y vuelve a entrar para aplicarlo. Con él oculto, el juego no dibuja ninguno de sus números, así que La del juego aparece en gris en las filas de arriba."
L["Log out and back in to apply: until then the game's floating text stays hidden."] = "Sal y vuelve a entrar para aplicarlo: hasta entonces el texto flotante del juego sigue oculto."
L["None hides all of the game's floating text, damage numbers included. It takes a log out and back in."] = "Ninguno oculta todo el texto flotante del juego, números de daño incluidos. Hay que salir y volver a entrar."
L["Each row sets many texts at once. You can change any of them afterward in the table below."] = "Cada fila ajusta muchos textos a la vez. Luego puedes cambiar cualquiera en la tabla de abajo."
L["Shows only your crits and misses, with plain hits and heals turned off."] = "Muestra solo tus críticos y fallos, sin los golpes y sanaciones normales."
L["Plain hits and heals are off and crits and misses are on. Switch any of them back in the table."] = "Los golpes y sanaciones normales están desactivados, y los críticos y fallos activados. Vuelve a cambiar cualquiera en la tabla."
L["Turns off your auto attacks, along with their crits and misses."] = "Desactiva tus ataques automáticos, junto con sus críticos y fallos."
L["Crits and your casts show in the middle, and the rest move aside."] = "Los críticos y tus lanzamientos se muestran en el centro, y el resto se aparta."
L["Your pet's hits show smaller than yours."] = "Los golpes de tu mascota se ven más pequeños que los tuyos."
L["Your pet's hits show as big as yours."] = "Los golpes de tu mascota se ven igual de grandes que los tuyos."
L["Every number is three quarters of the game's size."] = "Cada número tiene tres cuartos del tamaño del juego."
L["Swings are smaller, and spells and heals get bigger the longer their cast."] = "Los golpes normales son más pequeños, y los hechizos y sanaciones más grandes cuanto más largo es su lanzamiento."
L["Every number stays three quarters as long as the game's."] = "Cada número dura tres cuartos de lo que dura en el juego."
L["Swings stay up for less time, and spells and heals stay longer the longer their cast."] = "Los golpes normales duran menos, y los hechizos y sanaciones duran más cuanto más largo es su lanzamiento."
L["Puts everything on this tab back to its defaults."] = "Devuelve todo lo de esta pestaña a sus valores predeterminados."
L["How big it is compared to the game's."] = "Su tamaño comparado con el del juego."
L["How big its crits are compared to its hits."] = "El tamaño de sus críticos comparado con sus golpes."
L["Adds (Glancing), (Blocked) or (Resisted) after the number. In a fight, the amount is hidden."] = "Añade (Refilón), (Bloqueado) o (Resistido) tras el número. En combate, la cantidad se oculta."
L["How far it moves compared to the game's."] = "Cuánto se mueve comparado con el del juego."
L["How long it stays compared to the game's."] = "Cuánto dura comparado con el del juego."
L["How far into its time on screen it starts to fade."] = "En qué punto de su tiempo en pantalla empieza a desvanecerse."
L["Grows big for a moment, then settles, like the game's crits."] = "Crece un momento y luego se asienta, como los críticos del juego."
L["Shows or hides it. Turning it off hides the texts under it too, except crits, which have their own."] = "Lo muestra u oculta. Al desactivarlo también se ocultan los textos que tiene debajo, menos los críticos, que tienen el suyo."
L["This text's own look, on top of the one above it."] = "El aspecto propio de este texto, sumado al del que tiene encima."
L["Your own word in place of the game's (%s). Leave it empty to use the game's."] = "Tu propia palabra en lugar de la del juego (%s). Déjalo vacío para usar la del juego."

