L["Its ticks are three quarters of its hits' size."] = "Sus tics tienen tres cuartos del tamaño de sus golpes."
L["Shows this spell's numbers or not."] = "Muestra o no los números de este hechizo."
L["Its color. Right-click: its school's again."] = "Su color. Clic derecho: otra vez el de su escuela."
L["How big its numbers are. Right-click: its school's again."] = "El tamaño de sus números. Clic derecho: otra vez el de su escuela."
L["Its crits' color: its color unless set. Right-click: its color again."] = "El color de sus críticos: su color, si no se elige otro. Clic derecho: otra vez su color."
L["Its ticks (a DoT's, a channel's): the same as its hits, or smaller."] = "Sus tics (de un DoT o una canalización): iguales que sus golpes, o más pequeños."
L["More..."] = "Más..."
L["Every part of its look: its font, place and motion too."] = "Todo su aspecto: también su fuente, posición y movimiento."
L["Takes it off the list. Its numbers look like its school's again."] = "Lo quita de la lista. Sus números vuelven a verse como los de su escuela."
