L["Off on the Look tab"] = "Desactivado en la pestaña Aspecto"
L["No spells match."] = "Ningún hechizo coincide."
L["%d spells, %d with a look of their own"] = "%d hechizos, %d con aspecto propio"
L["Search your spells"] = "Busca tus hechizos"
L["Your spells that hit (this character)"] = "Tus hechizos que golpean (este personaje)"
L["Other spells in your spellbook"] = "Otros hechizos de tu libro de hechizos"
