-- Style/LetterboxStyle.lua
L["Preview:"] = "Vista previa:"
L["The weather the Preview shows."] = "El clima que muestra la Vista previa."
L["Shows this weather's tint at its heaviest for a few seconds (at 50% while Strength is Off)."] = "Muestra el tinte de este clima en su punto más fuerte durante unos segundos (al 50% mientras Intensidad está en Desactivado)."
L["On the screen"] = "En la pantalla"
L["Shows it for a few seconds, in CineMode or not (at 50% while it's Off)."] = "Lo muestra unos segundos, en CineMode o no (al 50% mientras está en Desactivado)."
L["Heavier weather"] = "Clima más intenso"
L["Medium"] = "Medio"
L["Heavy"] = "Fuerte"
L["Makes the game's own rain and snow thicker while its row is on, and puts yours back after."] = "Hace más densas la lluvia y la nieve del juego mientras su fila está activada, y luego devuelve las tuyas."
L["Pulls the view distance in as a downpour would, for a few seconds."] = "Acorta la distancia de visión como lo haría un chaparrón, durante unos segundos."
L["The world"] = "El mundo"
L["Draw the world between the bars"] = "Dibujar el mundo entre las franjas"
L["Shows the whole view between the bars instead of hiding its top and bottom (it changes only out of fights)."] = "Muestra toda la vista entre las franjas en vez de ocultar su parte de arriba y de abajo (solo cambia fuera de combate)."
L["Shows the whole time in CineMode, including fights and the Calm Timer after them."] = "Se muestra todo el rato en CineMode, también en combate y en el Temporizador de calma de después."
L["When on, the bars look the way this page sets them. When off, they're Cinematic's plain black bars."] = "Si está activado, las franjas se ven como dice esta página. Si no, son las franjas negras sencillas de Cinematic."
L["Takes the bars out and brings them back in, like at the start and end of a fight."] = "Quita las franjas y las vuelve a traer, como al empezar y acabar un combate."
L["Shapes the space between the bars like a movie screen, on any monitor."] = "Da al espacio entre las franjas forma de pantalla de cine, en cualquier monitor."
L["How tall the top bar is, as a share of the screen's height."] = "La altura de la franja de arriba, como parte de la altura de la pantalla."
L["Click to link or unlink the two bars. Linked, they're the same height."] = "Haz clic para unir o separar las dos franjas. Unidas, tienen la misma altura."
L["How tall the bottom bar is, as a share of the screen's height."] = "La altura de la franja de abajo, como parte de la altura de la pantalla."
L["How long the bars take to come in or go. Set to 0 to match the UI's fade."] = "Cuánto tardan las franjas en entrar o salir. Ponlo en 0 para que vaya con el desvanecido de la interfaz."
L["How the weather tints the scene: a color for each weather, and how fast it comes in and goes."] = "Cómo tiñe el clima la escena: un color para cada clima, y lo rápido que llega y se va."
L["When on, the weather uses the colors and time set here. When off, Cinematic's own."] = "Si está activado, el clima usa los colores y el tiempo de aquí. Si no, los de Cinematic."
L["Pick this weather's tint. White is no change; darker colors darken the scene more."] = "Elige el tinte de este clima. El blanco no cambia nada; los colores más oscuros oscurecen más la escena."
L["How long the weather's tint takes to come in as it starts, or to go as it clears or you step inside."] = "Cuánto tarda el tinte del clima en llegar cuando empieza, o en irse cuando escampa o entras a cubierto."

-- Style/MinimapStyle.lua
L["How the minimap looks: its shape, border and ring."] = "El aspecto del minimapa: su forma, su borde y su anillo."
L["Turns this page's minimap look on or off."] = "Activa o desactiva el aspecto del minimapa de esta página."
L["Size and shape"] = "Tamaño y forma"
L["How big the minimap is."] = "El tamaño del minimapa."
L["Makes the minimap square."] = "Hace cuadrado el minimapa."
L["Border size"] = "Tamaño del borde"
L["How thick the border round the square minimap is. 0: no border."] = "El grosor del borde del minimapa cuadrado. 0: sin borde."
L["Border color:"] = "Color del borde:"
L["Theme uses your theme's ring color, or black when it has none."] = "Tema usa el color de anillo de tu tema, o negro si no tiene."
L["Zone name and clock inside"] = "Zona y reloj dentro"
L["Puts the zone name at the top of the square minimap and the clock in its corner."] = "Pone el nombre de la zona arriba del minimapa cuadrado y el reloj en su esquina."
L["Zoom buttons"] = "Botones de zoom"
L["Hides the minimap's zoom buttons."] = "Oculta los botones de zoom del minimapa."
L["Hides the zone name bar over the minimap."] = "Oculta la barra con el nombre de la zona sobre el minimapa."
L["Hides the day and night dial on the minimap's edge."] = "Oculta la esfera de día y noche del borde del minimapa."
L["Ring and buttons"] = "Anillo y botones"
L["Colors the rings around minimap buttons in your theme's ring color, or the border color when it has none."] = "Pinta los anillos de los botones del minimapa con el color de anillo de tu tema, o con el color del borde si no tiene."
L["A little shading just inside the ring, so the map looks set into it."] = "Un poco de sombra justo dentro del anillo, para que el mapa parezca encajado en él."
L["Zone bar in the theme's look"] = "Barra de zona con el aspecto del tema"
L["Shade and the zone bar's look come with themes that have a ring color."] = "La sombra y el aspecto de la barra de zona vienen con los temas que tienen color de anillo."

-- Style/PersonalStyle.lua
L["When on, the bars look the way this page sets them. When off, they use the game's own look."] = "Si está activado, las barras se ven como dice esta página. Si no, usan el aspecto del juego."
L["It fades to a darker shade of its own color."] = "Se apaga hacia un tono más oscuro de su propio color."
L["Its width in screen pixels, so the same number gives two bars the same width."] = "Su ancho en píxeles de pantalla, así el mismo número da a dos barras el mismo ancho."
L["The health bar's width, growing out from its middle."] = "El ancho de la barra de salud, creciendo desde su centro."
L["The power bar's width, growing out from its middle."] = "El ancho de la barra de poder, creciendo desde su centro."
L["The mana bar's width as a percent of the game's power bar, growing out from its middle."] = "El ancho de la barra de maná como porcentaje de la barra de poder del juego, creciendo desde su centro."
L["The health bar's height compared to the game's."] = "La altura de la barra de salud comparada con la del juego."
L["The power bar's height compared to the game's."] = "La altura de la barra de poder comparada con la del juego."
L["How big your class resource is compared to the game's size."] = "El tamaño de tu recurso de clase comparado con el del juego."
L["The mana bar's height compared to the power bar's."] = "La altura de la barra de maná comparada con la de la barra de poder."
L["The bars' border: the game's or one of ours. Custom sets its thickness and color below."] = "El borde de las barras: el del juego o uno de los nuestros. Personalizado elige abajo su grosor y color."

-- Style/PlateCastStyle.lua
L["When on, the cast bars look the way this page sets them. When off, they use the game's own look."] = "Si está activado, las barras de lanzamiento se ven como dice esta página. Si no, usan el aspecto del juego."
L["Makes it part of the unit frame, with its fill, border and font, right under its bars."] = "La hace parte del marco de unidad, con su relleno, borde y fuente, justo bajo sus barras."
L["Pick the color of an interrupted cast. The game doesn't report this in every fight."] = "Elige el color de un lanzamiento interrumpido. El juego no lo avisa en todos los combates."
L["How dark it is behind the fill. This only works with a fill of your own; the game's keeps its own."] = "Lo oscuro que está detrás del relleno. Solo funciona con un relleno tuyo; el del juego mantiene el suyo."
L["Its width compared to the game's, growing out from its middle. Nameplates only."] = "Su ancho comparado con el del juego, creciendo desde su centro. Solo placas de nombre."
L["The cast bar's height compared to the game's."] = "La altura de la barra de lanzamiento comparada con la del juego."
L["The icon's size compared to the game's."] = "El tamaño del icono comparado con el del juego."
L["A dark shadow behind the letters, down and to the right."] = "Una sombra oscura detrás de las letras, abajo a la derecha."
L["The look every cast bar uses while its row is set to Default."] = "El aspecto que usa cada barra de lanzamiento mientras su fila está en Predeterminado."
L["Default's (Cast Bars)"] = "El de Predeterminado (Barras de lanzamiento)"

-- Style/QuestItemStyle.lua
L["When on, the button looks the way this page sets it. When off, it looks like the game's extra ability button."] = "Si está activado, el botón se ve como dice esta página. Si no, se ve como el botón de habilidad extra del juego."
L["Icons have their own dark border. Zooming in a little cuts it off."] = "Los iconos tienen su propio borde oscuro. Ampliarlos un poco lo recorta."
L["A black border around its numbers."] = "Un borde negro alrededor de sus números."

-- Style/QuestTalkStyle.lua
L["When on, the dialogue looks the way this page sets it. When off, it uses the game's parchment."] = "Si está activado, el diálogo se ve como dice esta página. Si no, usa el pergamino del juego."
L["The size of the bubble and the reply list. Their text grows with them."] = "El tamaño del bocadillo y de la lista de respuestas. Su texto crece con ellos."
L["A black border around the letters, for light text with no panel behind it."] = "Un borde negro alrededor de las letras, para texto claro sin panel detrás."
L["The bubble's text in a color of your own. The quest card keeps its own color."] = "El texto del bocadillo en un color que elijas. La tarjeta de misión mantiene su color."

-- Style/RaidStyle.lua
L["When on, the raid frames look the way this page sets them. When off, they use the game's own look."] = "Si está activado, los marcos de banda se ven como dice esta página. Si no, usan el aspecto del juego."
L["Uses the color below at full health, shifting to the At half and Empty colors as health drops."] = "Usa el color de abajo con la salud completa, y pasa a los colores A la mitad y Vacía según baja la salud."
L["Tints the game's background a color of your own, picked below."] = "Tiñe el fondo del juego con un color que elijas abajo."
L["The name's size compared to the game's."] = "El tamaño del nombre comparado con el del juego."
L["The look every group uses while its row is set to Same as the Default row."] = "El aspecto que usa cada grupo mientras su fila está en Igual que la fila Predeterminado."

-- Style/RollStyle.lua
L["When on, the window looks the way this page sets it. When off, it uses Roll Vision's usual look."] = "Si está activado, la ventana se ve como dice esta página. Si no, usa el aspecto normal de la Visión de tiradas."
L["A dark panel with a thin line around it, in the item's quality color."] = "Un panel oscuro con una línea fina alrededor, del color de la calidad del objeto."

