L["Shows the names near or far in the preview."] = "Muestra los nombres cerca o lejos en la vista previa."
L["Retail's plates size names by distance themselves."] = "Las placas de Retail ya ajustan el tamaño de los nombres según la distancia."
L["Size by"] = "Tamaño según"
L["Names grow as you zoom in and shrink as you zoom out."] = "Los nombres crecen al acercar la cámara y se encogen al alejarla."
