L["Far size"] = "Tamaño lejos"
L["Close raise"] = "Altura cerca"
L["Far raise"] = "Altura lejos"
L["Distance settings are the same for every name: they're on Default."] = "Las opciones de distancia son iguales para todos los nombres: están en Predeterminado."
L["A drop shadow behind the letters, with a thick outline."] = "Una sombra detrás de las letras, con un contorno grueso."
L["Speech from behind you shows once these are on: %s."] = "Lo que se dice a tu espalda se muestra cuando esto está activado: %s."
