L["On out of combat, once the Calm Timer after a fight has run out."] = "Activado fuera de combate, cuando se ha agotado el Temporizador de calma tras un combate."
L["Uses your choice in the game's options. If that's Off, nothing shows here."] = "Usa lo que elegiste en las opciones del juego. Si ahí está desactivado, aquí no se muestra nada."

