-- UI/RuleEditor.lua
L["Up and down to choose, Tab or Enter to take, Escape to close"] = "Arriba y abajo para elegir, Tab o Intro para aceptar, Esc para cerrar"
L["Find a word"] = "Buscar una palabra"
L["Searches every word by its name, what you'd type and what it means. Enter adds the first."] = "Busca cada palabra por su nombre, por lo que escribirías y por lo que significa. Intro añade la primera."
L["Drops the rule, so the row's dropdowns decide again, ticked as they were before."] = "Quita la regla, así los desplegables de la fila vuelven a decidir, marcados como estaban."
L["Both sides true. A word added after a word gets AND by itself."] = "Los dos lados se cumplen. Una palabra añadida tras otra lleva AND automáticamente."
L["Either side true. Right after an AND that was added for you, it takes its place."] = "Se cumple cualquiera de los dos lados. Justo después de un AND que se puso solo, ocupa su lugar."
L["The next word or brackets false. Shift-click a word to add it with NOT."] = "La siguiente palabra o paréntesis no se cumple. Haz Mayús+clic en una palabra para añadirla con NOT."
L["Opens a group, around what you add next."] = "Abre un grupo alrededor de lo que añadas después."
L["Closes the group."] = "Cierra el grupo."
L["Undoes the last change (Ctrl+Z)."] = "Deshace el último cambio (Ctrl+Z)."
L["Does it again (Ctrl+Y)."] = "Lo vuelve a hacer (Ctrl+Y)."
L["Nothing to pick here now"] = "Ahora no hay nada que elegir aquí"
L["Opens a menu of what's here and what you have."] = "Abre un menú con lo que hay aquí y lo que tienes."
L["True where you stand now."] = "Se cumple donde estás ahora."
L["False where you stand now."] = "No se cumple donde estás ahora."
L["Click adds it; Shift-click adds NOT %s."] = "Clic la añade; Mayús+clic añade NOT %s."
L["Words for \"%s\""] = "Palabras para \"%s\""
L["%d found"] = "%d encontradas"
L["No word matches. Try what it does: stun, buff, yards..."] = "Ninguna palabra coincide. Prueba con lo que hace: aturdir, beneficio, metros..."
L["True here"] = "Se cumple aquí"
L["In this rule"] = "En esta regla"
L["Everything true where you stand now."] = "Todo lo que se cumple donde estás ahora."
L["The words this rule uses."] = "Las palabras que usa esta regla."
L["Nothing is true here now."] = "Ahora aquí no se cumple nada."
L["The rule has no words yet."] = "La regla aún no tiene palabras."
