L["%s is ticked, but a switch over it is off"] = "%s está marcado, pero un interruptor por encima está desactivado"

-- Visions/CardsPage.lua
L["The card types cards start from. A change to one applies to every card using it."] = "Los tipos de tarjeta de los que parten las tarjetas. Un cambio en uno se aplica a todas las tarjetas que lo usan."
L["Click to preview it and light up its cards below."] = "Haz clic para verlo y resaltar sus tarjetas abajo."
L["Its own settings over its card type: %s."] = "Sus opciones propias sobre su tipo de tarjeta: %s."
L["Its cards on or off, and where each shows."] = "Sus tarjetas activadas o no, y dónde se muestra cada una."
L["Resets this card's own settings so they come from its card type again."] = "Restablece las opciones propias de esta tarjeta para que vuelvan a venir de su tipo de tarjeta."
L["Puts all your changes to this card type back to the defaults."] = "Devuelve todos tus cambios en este tipo de tarjeta a los valores predeterminados."
L["No new Zone or Subzone card for this long after one. Set to 0 to show one every time."] = "No sale otra tarjeta de Zona o Subzona durante este tiempo tras una. Ponlo en 0 para que salga siempre."
L["The words as you go into a fight against players; leave empty for none."] = "Las palabras al entrar en un combate contra jugadores; déjalo vacío para ninguna."
L["No card after fights shorter than this. Set to 0 for every fight."] = "Sin tarjeta tras combates más cortos que esto. Ponlo en 0 para todos los combates."
L["The opening words (on a card, over the zone name)."] = "Las palabras de entrada (en una tarjeta, sobre el nombre de la zona)."
L["Its usual card, in its own look (the Style tab)."] = "Su tarjeta normal, con su propio aspecto (la pestaña Estilo)."
L["A picture in its own colors: red with a dark outline on a flat black band."] = "Un dibujo con sus propios colores: rojo con contorno oscuro sobre una banda negra lisa."
L["Shows the line only this long at the start and end. All the way left (Off) shows it the whole way."] = "Muestra la línea solo este tiempo al principio y al final. Del todo a la izquierda (Desactivado) la muestra todo el rato."

-- Visions/CombatSoundRules.lua
L["How loud the sounds are, compared to your sound effects volume."] = "Lo fuerte que suenan los sonidos, comparado con tu volumen de efectos de sonido."
L["This sound's volume, compared to the others."] = "El volumen de este sonido, comparado con los demás."
L["Resets this card's rules to the defaults."] = "Restablece las reglas de esta tarjeta a las predeterminadas."
L["Resets this tab to its default rules: one sound as any other fight starts and one as it ends."] = "Restablece esta pestaña a sus reglas predeterminadas: un sonido al empezar cualquier otro combate y otro al acabar."

-- Visions/DamageVision.lua
L["Shows in every fight, wherever you are, so the other columns don't matter."] = "Se muestra en todos los combates, estés donde estés, así que las demás columnas no importan."
L["Shows how you did on that boss as it dies."] = "Muestra qué tal te fue con ese jefe cuando muere."
L["Shows how you did on the whole run once it's done."] = "Muestra qué tal te fue en toda la partida cuando acaba."
L["Shows the recap card with the meter's whole run if you have one, or a made-up one if not (Stop hides it)."] = "Muestra la tarjeta de resumen con toda la partida del medidor si tienes una, o una inventada si no (Detener la oculta)."
L["Shows your place over it (#2)."] = "Muestra tu puesto encima (#2)."
L["A crown pops in as you take #1."] = "Aparece una corona cuando te pones #1."
L["Shows the name of the one you race, in their class's color."] = "Muestra el nombre de con quien compites, del color de su clase."
L["Shows your damage (or healing) so far."] = "Muestra tu daño (o sanación) hasta ahora."
L["Shows each player's name on their row."] = "Muestra el nombre de cada jugador en su fila."
L["Amber while you're behind, teal once you lead, or two colors of your own."] = "Ámbar mientras vas por detrás, verde azulado cuando vas en cabeza, o dos colores que elijas."

-- Visions/EmoteVision.lua
L["Emote Vision test: you'd %s."] = "Prueba de Visión de gestos: harías %s."
L["Turn it on and pick which moments show a card, and the emotes on each."] = "Actívalo y elige qué momentos muestran una tarjeta, y las emociones de cada uno."
L["Cards that need the other player's nameplate. CineMode keeps it for them."] = "Tarjetas que necesitan la placa de nombre del otro jugador. CineMode se la mantiene."
L["Puts the menu's emotes back to the defaults."] = "Devuelve las emociones del menú a las predeterminadas."
L["Shows wherever you are, but never in a fight. A card that comes up in a fight waits for it to end."] = "Se muestra estés donde estés, pero nunca en combate. Una tarjeta que salga en combate espera a que acabe."
L["Puts every moment's emotes back to the defaults."] = "Devuelve las emociones de cada momento a las predeterminadas."
L["Only buffs from strangers bring up a card, not buffs from your party or raid."] = "Solo los beneficios de desconocidos muestran una tarjeta, no los de tu grupo o banda."
